  family: "valheim",
  label: "Valheim",
  defaultVariant: "vanilla",
  variants: [
    { id: "vanilla", label: "Vanilla", description: "Standard dedicated server." },
    { id: "bepinex", label: "BepInEx", description: "BepInEx modding framework for Valheim mods." },
  ],
  // New Valheim orders start on BepInEx with crossplay on (2026-10-02, prd-003):
  // 2 of the 4 live servers were vanilla, so the mods their owners installed
  // could never load, and a console friend couldn't join until crossplay was
  // found in Settings. Existing servers are untouched (see FamilySchema.orderDefaults).
  // Crossplay default turned OFF (2026-10-06, owner): with -crossplay Valheim uses
  // PlayFab and never opens its game port, so PC players connecting by IP:port (what
  // the dashboard shows) can't join and the panel reports "not accepting connections".
  // Customers who need console/Xbox friends switch it on in Settings.
  orderDefaults: { variant: "bepinex", values: { CROSSPLAY: false } },
