    // password, with no way to see or change it (a real customer ticket: "I
    // don't see the server password anywhere, can I change it?"). `required`
    // so checkout forces a real value in from day one, same precedent as
    // DST's TOKEN field above.
    {
      key: "SERVER_PASS",
      label: "Server password",
      group: "General",
      type: "string",
      default: "",
      phase: "deploy",
      required: true,
      minLength: 5,
      notInsideField: "world",
      suggest: "password",
      help: "Valheim requires a password of at least 5 characters (and it can't be part of the world name). We've suggested one — change it if you like; you can edit it later in Settings.",
    },
    // Added 2026-10-01 (customer Jay: console players find servers by NAME in the
    // in-game browser, and the name was hardcoded 'Nxeon' in prisma/catalog.ts's
    // setupScript, with no way to change it). Maps to lloesche/valheim-server's
    // SERVER_NAME env (`-name`). Default stays "Nxeon" = today's behaviour; the
    // apply path (worker/game-config.ts applyValheim) treats the untouched
    // default as "leave the running name alone", so saving other settings never
    // renames an existing server. Rules (Valheim itself publishes no hard limit;
    // these are conservative and shell-inert, the name travels through an
    // env-file and a quoted bash expansion): 3-64 characters; letters, digits,
    // spaces and  - _ . ' ! & ( ) [ ] + , # : ~ @ |  only; no leading/trailing
    // space; must not contain the server password (the game refuses to start
    // when it does; that cross-field rule is enforced in applyValheim).
    {
      key: "SERVER_NAME",
      label: "Server name",
      group: "General",
      type: "string",
      default: "Nxeon",
      phase: "deploy",
      minLength: 3,
      maxLength: 64,
      pattern: "^[\\p{L}\\p{N}][\\p{L}\\p{N} _.'!&()\\[\\]+,#:~@|-]*[\\p{L}\\p{N}.!)\\]]$",
      patternError:
        "Server name: use letters, numbers, spaces and - _ . ' ! & ( ) [ ] + , # : ~ @ | only, and start/end with a letter, number or . ! ) ].",
      help:
        "The name players see in the in-game server list (console players search by this). Leave as Nxeon to keep your current name. Must not contain your password.",
    },
    {
      key: "world",
      envKey: "WORLD_NAME",
      label: "World name",
      group: "World",
      type: "string",
      default: "Dedicated",
      phase: "deploy",
      help: "-world — the save file to load. A new name creates a fresh world.",
    },
    {
      key: "preset",
      label: "World modifier preset",
      group: "World",
      type: "enum",
      default: "normal",
      // applyValheim is always a full container recreate for any field change —
      // there is no live push mechanism at all (2026-09-10 audit).
      phase: "deploy",
      options: [
        { value: "normal", label: "Normal" },
        { value: "casual", label: "Casual" },
        { value: "easy", label: "Easy" },
        { value: "hard", label: "Hard" },
        { value: "hardcore", label: "Hardcore" },
        { value: "immersive", label: "Immersive" },
        { value: "hammer", label: "Hammer (creative)" },
      ],
      help: "-preset — global combat/resource modifiers.",
    },
    // Individual modifier overrides, distinct from the combined `preset`
    // above — Valheim itself lets these be tuned independently of whichever
    // preset is active. Values verified against the game's own known
    // -modifier value set (not guessed): deathpenalty accepts casual/
    // veryeasy/easy/normal/hard/hardcore, portals accepts casual/normal/
