        { value: "easy", label: "Easy" },
        { value: "normal", label: "Normal" },
        { value: "hard", label: "Hard" },
        { value: "hardcore", label: "Hardcore (lose skills)" },
      ],
      help: "-modifier deathpenalty — what's lost on death.",
    },
    {
      key: "portals",
      label: "Portal restrictions",
      group: "World",
      type: "enum",
      default: "normal",
      phase: "deploy",
      options: [
        { value: "casual", label: "Casual (all metals allowed)" },
        { value: "normal", label: "Normal" },
        { value: "hard", label: "Hard" },
        { value: "veryhard", label: "Very hard (no portals)" },
      ],
      help: "-modifier portals — what can be sent through portals.",
    },
    // "normal" is this field's default/no-override choice, same convention as
