    {
      key: "raids",
      label: "Raid frequency",
      group: "World",
      type: "enum",
      default: "normal",
      phase: "deploy",
      options: [
        { value: "none", label: "None (raids off)" },
        { value: "muchless", label: "Much less" },
        { value: "less", label: "Less" },
        { value: "normal", label: "Normal" },
        { value: "more", label: "More" },
        { value: "muchmore", label: "Much more" },
      ],
      help: "-modifier raids — how often random raid events occur.",
    },
    {
      key: "ADMINLIST_IDS",
      label: "Admin SteamIDs",
      group: "Access",
      type: "string",
      default: "",
      phase: "deploy",
      help: "Space-separated SteamID64s. Admins can kick/ban from the F5 console, and after typing devcommands can run server commands such as sleep and skiptime. god, fly and debugmode also need the Nxeon Dev Admin plugin on that admin's own PC (ask support).",
    },
    {
      key: "PERMITTEDLIST_IDS",
      label: "Whitelisted SteamIDs",
      group: "Access",
      type: "string",
      default: "",
      phase: "deploy",
      help: "Space-separated SteamID64s. Blank = anyone with the server password may join.",
    },
    {
      key: "CROSSPLAY",
      label: "Crossplay",
