/** Clamp/validate a raw value against its field; unknown enum values fall back to the default. */
export function cleanValue(f: GenField, raw: unknown): string | number | boolean {
  if (f.type === "bool") return raw === true || raw === "true";
  if (f.type === "int") { const n = Math.round(Number(raw)); return Number.isFinite(n) ? Math.min(f.max, Math.max(f.min, n)) : f.default; }
  return f.options.some((o) => o.value === String(raw)) ? String(raw) : f.default;
}

const iniVal = (f: GenField, v: string | number | boolean) =>
  f.type === "bool" ? (v ? "True" : "False") : f.type === "int" ? String(v) : /^[0-9.]+$/.test(String(v)) ? Number(v).toFixed(6) : String(v);

export function palworldIni(values: GenValues): string {
  const parts = PALWORLD_FIELDS.filter((f) => f.ini).map((f) => `${f.ini}=${iniVal(f, cleanValue(f, values[f.id] ?? f.default))}`);
  return `[/Script/Pal.PalGameWorldSettings]\nOptionSettings=(${parts.join(",")})`;
}

export function palworldEnv(values: GenValues): string {
  return PALWORLD_FIELDS.filter((f) => f.env).map((f) => {
    const v = cleanValue(f, values[f.id] ?? f.default);
    return `${f.env}=${f.type === "bool" ? (v ? "True" : "False") : f.id === "expRate" ? Number(v).toFixed(6) : String(v)}`;
  }).join("\n");
}

