const lvl = (vals: [string, string][]) => vals.map(([value, label]) => ({ value, label }));
export const VALHEIM_FIELDS: GenField[] = [
  { id: "preset", label: "World modifier preset", group: "Preset", type: "enum", default: "normal", source: "schema", help: "A preset sets all modifiers at once and overrides the individual ones below.", options: lvl([["normal", "Normal"], ["casual", "Casual"], ["easy", "Easy"], ["hard", "Hard"], ["hardcore", "Hardcore"], ["immersive", "Immersive"], ["hammer", "Hammer (creative)"]]) },
  { id: "combat", label: "Combat", group: "Modifiers", type: "enum", default: "normal", source: "community", help: "Enemy damage and difficulty.", options: lvl([["normal", "Normal (no override)"], ["veryeasy", "Very easy"], ["easy", "Easy"], ["hard", "Hard"], ["veryhard", "Very hard"]]) },
  { id: "deathpenalty", label: "Death penalty", group: "Modifiers", type: "enum", default: "normal", source: "schema", help: "What is lost on death.", options: lvl([["casual", "Casual (keep everything)"], ["veryeasy", "Very easy"], ["easy", "Easy"], ["normal", "Normal (no override)"], ["hard", "Hard"], ["hardcore", "Hardcore (lose skills)"]]) },
  { id: "resources", label: "Resources", group: "Modifiers", type: "enum", default: "normal", source: "community", help: "How much you gather per action.", options: lvl([["muchless", "Much less"], ["less", "Less"], ["normal", "Normal (no override)"], ["more", "More"], ["muchmore", "Much more"]]) },
  { id: "raids", label: "Raids", group: "Modifiers", type: "enum", default: "normal", source: "schema", help: "How often base raids happen.", options: lvl([["none", "None (raids off)"], ["muchless", "Much less"], ["less", "Less"], ["normal", "Normal (no override)"], ["more", "More"], ["muchmore", "Much more"]]) },
  { id: "portals", label: "Portals", group: "Modifiers", type: "enum", default: "normal", source: "schema", help: "What may travel through portals.", options: lvl([["casual", "Casual (all metals allowed)"], ["normal", "Normal (no override)"], ["hard", "Hard"], ["veryhard", "Very hard (no portals)"]]) },
  { id: "playerevents", label: "Events only near players", group: "World keys", type: "bool", default: false, source: "community", help: "Raids and events only trigger while a player is near their base (-setkey playerevents)." },
];

export interface ValheimBasics { name: string; world: string; password: string; port: number; crossplay: boolean }
const q = (s: string) => `"${s.replace(/["\\$`]/g, "")}"`;

export function valheimArgs(values: GenValues, basics: ValheimBasics): string {
  const out = [`-name ${q(basics.name || "My Server")}`, `-port ${basics.port || 2456}`, `-world ${q(basics.world || "Dedicated")}`, `-password ${q(basics.password || "change-me")}`];
  if (basics.crossplay) out.push("-crossplay");
  const preset = cleanValue(VALHEIM_FIELDS[0], values.preset ?? "normal");
  if (preset !== "normal") out.push(`-preset ${preset}`);
  for (const f of VALHEIM_FIELDS.slice(1, 6)) {
    const v = String(cleanValue(f, values[f.id] ?? f.default));
    if (v !== "normal") out.push(`-modifier ${f.id} ${v}`);
  }
  if (cleanValue(VALHEIM_FIELDS[6], values.playerevents) === true) out.push("-setkey playerevents");
  return out.join(" ");
}

/** A preset overrides individual modifiers: list the modifiers that will be ignored. */
export function valheimOverridden(values: GenValues): string[] {
  if (cleanValue(VALHEIM_FIELDS[0], values.preset ?? "normal") === "normal") return [];
  return VALHEIM_FIELDS.slice(1, 6).filter((f) => String(cleanValue(f, values[f.id] ?? f.default)) !== "normal").map((f) => f.id);
}
test("IndexNow URL normalisation drops foreign hosts and duplicates", () => {
  const out = normalizeIndexNowUrls(["/a", "https://nxeon.cloud/a", "https://evil.example/x", "b"], "https://nxeon.cloud");
  assert.deepEqual(out, ["https://nxeon.cloud/a", "https://nxeon.cloud/b"]);
});

import { palworldIni, palworldEnv, valheimArgs, valheimOverridden, cleanValue, PALWORLD_FIELDS } from "../lib/tools/config-generators";

test("palworld ini + env reflect chosen values and clamp bad input", () => {
  const ini = palworldIni({ expRate: "3", players: 999, pvp: true, deathPenalty: "bogus" });
  assert.match(ini, /^\[\/Script\/Pal\.PalGameWorldSettings\]\nOptionSettings=\(/);
  assert.match(ini, /ExpRate=3\.000000/);
  assert.match(ini, /ServerPlayerMaxNum=32/);
  assert.match(ini, /DeathPenalty=All/); // invalid enum -> default
  assert.ok(!ini.includes("IS_PVP"));
  assert.match(palworldEnv({ pvp: true, expRate: "2" }), /IS_PVP=True\n?[\s\S]*EXP_RATE=2\.000000/);
  assert.equal(cleanValue(PALWORLD_FIELDS.find((f) => f.id === "guild")!, "-5"), 1);
});

test("valheim args only emit overrides, strip quotes, flag preset conflicts", () => {
  const basics = { name: 'My "Hall"', world: "Dedicated", password: "secret1", port: 2456, crossplay: true };
  assert.equal(valheimArgs({}, basics), '-name "My Hall" -port 2456 -world "Dedicated" -password "secret1" -crossplay');
  const a = valheimArgs({ deathpenalty: "hardcore", raids: "none", playerevents: true }, basics);
  assert.match(a, /-modifier deathpenalty hardcore -modifier raids none -setkey playerevents$/);
  assert.deepEqual(valheimOverridden({ preset: "hard", raids: "none", combat: "normal" }), ["raids"]);
  assert.ok(!valheimArgs({ preset: "bogus" }, basics).includes("-preset"));
});
