/** Replace `<flag> <value>` in an argument string, or append the pair if absent. */
function upsertArg(args: string, flag: string, value: string): string {
  const esc = flag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp(`(^|\\s)${esc}\\s+\\S+`);
  return re.test(args) ? args.replace(re, `$1${flag} ${value}`) : `${args} ${flag} ${value}`.trim();
}

/** Strip `<flag> <value>` from an argument string entirely, if present. */
function removeArg(args: string, flag: string): string {
  const esc = flag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp(`(^|\\s)${esc}\\s+\\S+`);
  return args.replace(re, "").trim();
}

/** Replace `+convar <value>` in a Rust startup-argument string, or append it. */
function upsertConvarArg(args: string, convar: string, value: string): string {
  return upsertArg(args, `+${convar}`, value);
}

