  // Originally gated on the variant alone — found live 2026-09-11 that this
  // missed the far more common case: a customer keeps the DEFAULT variant but
  // customizes other fields the setup script's static `-e KEY=` string can
  // never express (Valheim's deathpenalty/portals are `-modifier` CLI flags,
  // not env vars — applyGameConfigEnv structurally can't produce them). Those
  // sat unapplied — the server ran on catalog defaults — until the customer
  // happened to open Settings and hit Save, sometimes a full day later. Now
  // also fires whenever any checkout-time gameConfig value differs from that
  // field's schema default, so a fresh order gets everything it paid for
  // applied for real before any player ever connects. Safe to over-trigger:
  // applyValheim (and the other per-family real-apply functions) already
  // no-op when nothing they check actually differs from what's running.
  try {
    const gameFamily = gameFamilyForServer(server as unknown as ServerFamilyLike);
    const schema = gameFamily ? schemaFor(gameFamily) : null;
    const gameConfig = (server.gameConfig as Record<string, unknown> | null) ?? {};
    const minted: string[] = (server as any).__mintedConfigKeys ?? [];
    const hasNonDefaultConfig = !!schema && schema.fields.some((f) => {
      if (minted.includes(f.key)) return false; // already baked into the setup script
      const val = gameConfig[f.key];
      return val !== undefined && val !== null && String(val) !== String(f.default);
    });
    // File-based appliers (lib/game-config-appliers.ts applyAtProvision) must run once even on all-default
    // values: the config file only exists after first boot, so nothing else can seed the page's defaults.
    const applyAtProvision = !!gameFamily && !!applierSpec(gameFamily)?.applyAtProvision;
    if (schema && ((server.gameVariant && server.gameVariant !== schema.defaultVariant) || hasNonDefaultConfig || applyAtProvision)) {
      await db.job.create({ data: { type: "GAME_CONFIG", serverId: server.id } });
    }
  } catch (e) {
    console.error(`[worker] could not auto-queue GAME_CONFIG for ${server.hostname}'s checkout-time variant`, e);
