/**
 * Valheim world modifiers beyond preset/deathpenalty/portals/raids (2026-10-14).
 *
 * Verified against Valheim's own "A guide to dedicated servers"
 * (https://www.valheim.com/support/a-guide-to-dedicated-servers/):
 *   -modifier Combat:    veryeasy, easy, hard, veryhard
 *   -modifier Resources: muchless, less, more, muchmore, most
 *   -setkey (checkbox keys): nobuildcost, playerevents, passivemobs, nomap
 * As with the existing modifiers, "normal" / false means "no override" and the
 * flag is stripped (the game rejects a literal `normal`).
 *
 * SERVER_ARGS is expanded UNQUOTED by the image, so every token written here comes
 * from the fixed allowlists below, never from raw input.
 */
export const VALHEIM_COMBAT_VALUES = new Set(["veryeasy", "easy", "normal", "hard", "veryhard"]);
export const VALHEIM_RESOURCES_VALUES = new Set(["muchless", "less", "normal", "more", "muchmore", "most"]);
/** Schema field key (also the -setkey name) in the stable output order. */
export const VALHEIM_SETKEYS = ["nobuildcost", "playerevents", "passivemobs", "nomap"] as const;

const MODIFIERS: ReadonlyArray<readonly [string, ReadonlySet<string>]> = [
  ["combat", VALHEIM_COMBAT_VALUES],
  ["resources", VALHEIM_RESOURCES_VALUES],
];

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const truthy = (v: unknown) => v === true || v === "true" || v === "on";

export interface ValheimModifierPlan {
  args: string;
  applied: string[];
  notes: string[];
}

/**
 * Pure: rewrite a SERVER_ARGS string for the new modifiers. A key that is absent
 * from `values` is left exactly as it is in `args`. Present keys: previous
 * occurrence removed, then non-default ones appended in fixed order
 * (combat, resources, nobuildcost, playerevents, passivemobs, nomap). Unknown or
 * injection-shaped values are ignored with a note and the existing flag is kept.
 */
export function planValheimModifierArgs(args: string, values: Record<string, unknown>): ValheimModifierPlan {
  let out = args;
  const applied: string[] = [];
  const notes: string[] = [];
  const add: string[] = [];
  const strip = (re: string) => {
    out = out.replace(new RegExp(`(^|\\s)${re}(?=\\s|$)`, "g"), "").replace(/\s+/g, " ").trim();
  };
  for (const [key, valid] of MODIFIERS) {
    if (values[key] == null) continue;
    const value = String(values[key]);
    if (!valid.has(value)) {
      notes.push(`Ignored an unrecognised ${key} value "${value}".`);
      continue;
    }
    strip(`-modifier\\s+${key}\\s+\\S+`);
    if (value !== "normal") add.push(`-modifier ${key} ${value}`);
    applied.push(key);
  }
  for (const key of VALHEIM_SETKEYS) {
    if (values[key] == null) continue;
    strip(`-setkey\\s+${esc(key)}`);
    if (truthy(values[key])) add.push(`-setkey ${key}`);
    applied.push(key);
  }
  if (add.length) out = `${out} ${add.join(" ")}`.trim();
  return { args: out, applied, notes };
}

/** Read the new modifiers back out of a SERVER_ARGS string (inverse of the planner). */
export function parseValheimModifierArgs(args: string): Record<string, string | boolean> {
  const out: Record<string, string | boolean> = {};
  for (const [key, valid] of MODIFIERS) {
    const m = new RegExp(`(?:^|\\s)-modifier\\s+${key}\\s+(\\S+)(?=\\s|$)`).exec(args);
    out[key] = m && valid.has(m[1]) ? m[1] : "normal";
  }
  for (const key of VALHEIM_SETKEYS) {
    out[key] = new RegExp(`(?:^|\\s)-setkey\\s+${esc(key)}(?=\\s|$)`).test(args);
  }
  return out;
}
EOF
